INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('koz', 'Parameters: BD ### mmHg, Pols:###bpm, T:###°c, Sat.###%, AHfreq: ###/min, G: ###kg (###kg). Algemeen: Comfortabele patiënt. Euvolemisch. Cor: S1S2, RR. Geen souffles of bijgeluiden. Pulm: VAG Bilateraal, geen bijgeluiden. Abd: Soepel, pijnvrij. Normoperistalsis &-tympaan. Geen organomegalie. Ledematen: Geen oedemen. Sterke perifere pulsaties. Derm: Geen afwijkingen. Vrije klierstreken. NKO: geen adenopathieen. Pharynx: nl. Neuro: PEARL, craniale zenuwen ok. Bilateraal symm. kracht in O- & BL.', '8798.0');
