INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('SA', 'Systeemanamnestisch: Alg: Geen koorts, nachtzweten of gewichtsveranderingen. Car: Geen klachten van claudicatio, dyspnee, thoracale pijn, palpitaties of syncopes. Pulm: Geen hoest, sputa of dyspnee. Geen dysfonie. Abd: Geen abdominale klachten, stoelgangsveranderingen of melena. Geen nausea of vomitus. Geen pyrosis of regurgitaties. Sys: Geen raynaudfenomenen. Geen siccaklachten. Geen gewrichtsklachten. Der: Geen dermale veranderingen of nieuwe letsels. Neu: Gehoor en visus stabiel. Onveranderde kracht en sensoriek.', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('NFR', 'We benadrukken het verdere belang tot nemen van conservatieve maatregelen (zoutbeperking, strikte bloeddrukcontrole, vermijden van nefrotoxische medicatie, vermijden van radiocontrast en snelle aanpak van episodes van dehydratatie of ondervulling).', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('CIAL', 'We werden voor IAL in consult gevraagd bij uw ###-jarige patiënt. Reden van consult: ------------------ ### Medische voorgeschiedenis: ------------------------- * ### Huidige problematiek: -------------------- ### * Antibiotica: ### * Culturen: ### Klinisch onderzoek: ------------------- Parameters: BD ### mmHg, Pols: ###, T:###°c. Algemeen: Comfortabele patiënt. Euvolemisch. Cor: S1S2, RR. Geen souffles of bijgeluiden. Pulm: VAG Bilateraal, geen bijgeluiden. Abd: Soepel, pijnvrij. Normoperistalsis &-tympaan. Geen organomegalie. Ledematen: Geen oedemen. Sterke perifere pulsaties. Homan:###. Derm: Geen afwijkingen. Vrije klierstreken. Neuro: PEARL, craniale zenuwen ok. Bilateraal symm. kracht in O- & BL. BESPREKING EN BESLUIT ===================== We werden voor IAL in consult gevraagd bij uw ###-jarige patiënt. Gelieve ### een nieuw consult te vragen. Verder advies op uw vraag.', '8798.0');
