INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('card', 'Uw ###-jarige patiënt, ###, werd opgenomen op de dienst cardiologie van ### t.e.m ###. Wij bemerken het volgende: 1. Electieve opname voor ### omwille van ### 2. Op het vlak van secundaire cardiovasculaire preventie weerhouden we de volgende streefwaarden : - Bloeddruk : < 130 mmHg systolisch, < 80 mmHg systolisch. - Lipiden : cholesterol < 170 mg/dl, LDL < 70 mg/dl doch preferentiëel zo laag mogelijk. Te controleren op nuchtere bloedname. - Glycemie : nuchtere glycemie < 100 mg/dl of HbA1c < 7.0%. Te controleren op nuchtere bloedname. - BMI : < 25 kg/m² - Hygiënisch : minstens 2x30 minuten per dag matige fysieke inspanning, aangepaste zoutarme voeding, vermagering tot BMI < 25 kg/m2, - Blijvende rookstop.', '8798.0');
