INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('desenss', 'De rush-desensibilisatie behelst een korte opname van 3.5 dagen tijdens dewelke snel oplopende dossisen wespengif worden toegediend. Na deze kuur is uw patiënt in principe beschermd tegen ernstige systemische symptomen bij volgende ###. In principe is Uw patiënt vanaf nu beschermd voor veralgemeende reacties volgende bijensteken, maar verdere ambulante vaccinatieszijn nodig om deze tolerantie in stand te houden. Bedoeling is dat het interval tussen 2 opeenvolgende injecties telkens met een week verhoogd wordt tot een interval van 12 weken. Nadien blijft in principe 1 injectie/3 maand aangehouden gedurende een verdere 2-3 jaar waarna een re-evaluatie volgt en afhankelijk daarvan kan beslist worden om het interval al dan niet verder te verlengen. ###', '8798.0');
