INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('HIVI', 'Voorafgaandelijk aan start van nieuwe medicatie dient steeds te worden nagegaan of er geen significante geneesmiddeleninteracties zijn, in casu voor enkele geneesmiddelen met dolutegravir. Dit kan gebeuren op de website http://www.hiv-druginteractions.org of in telefonisch overleg met onze dienst. ###', '8798.0');
