INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('folfoxx', '* Modified FOLFOX In dit chemotherapie schema wordt het alkylerend agens Oxaliplatin toegediend aan een dosis van 85mg/m² op dag 1 in combinatie met Elvorine 200mg/m² op dag 1 en 5-Fluoro-Uracyl (5FU) bolus 400mg/m² op dag 1 en vervolgens 5FU continu infuus (2400mg/m²) via infusor op dag1 over 48 uur. Op dag 3 wordt de infusor verwijderd door de thuisverpleging. Dit schema wordt 2 wekelijks herhaald. Mogelijke nevenwerkingen van oxaliplatin zijn nausea, braken, myelosuppressie (anemie, leucopenie en trombopenie), diarree, mucositis, perifere neuropathie, vermoeidheid, anorexie en krampen (getriggerd door koude). Drinken van koude (en warme dranken) dient vermeden worden tijdens de toediening van de chemotherapie) Mogelijke nevenwerkingen van 5-FU zijn diarree, nausea en braken, mucositis, anorexie, waterige ogen, smaakverlies, myelumsuppressie, nagelveranderingen, droge huid en zelden hand-voet syndroom', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('cismdgg', '* Cisplatinum 23 De Gramont In dit chemotherapieschema wordt op dag1 het alkylerend agens cisplatinum toegediend aan een dosis van 50 mg/m² voorafgegaan door prehydratatie. Op dag 1 en 2 wordt het De Gramont schema toegediend. Hier bij wordt Elvorin 100 mg/m² op dag 1 en dag 2 toegediend, een bolus 5-Fluoro-Uracil (5FU) gegeven van 400 mg/m² op dag 1 en dag 2, en vervolgens via continu infuus 5-FU aan een dosis van 600 mg/m²/dag op dag 1 en dag 2. De derde dag wordt het pompje 5-FU afgeschakeld. Het hele schema cisplatinum - De Gramont wordt 2-wekelijks herhaald. Mogelijke nevenwerkingen van cisplatinum zijn nausea, braken, myelosuppressie (anemie, leucopenie en trombopenie), vermoeidheid, diarree, stomatitis, smaakveranderingen, anorexie, neurotoxiciteit, ototoxiciteit, nefrotoxiciteit en soms alopecie. Mogelijke nevenwerkingen van 5-FU zijn diarree, nausea en braken, mucositis, anorexie, waterige ogen, smaakverlies, myelumsuppressie, nagelveranderingen, droge huid en zelden hand-voet syndroom.', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('folfirii', 'In dit chemotherapie schema wordt de topo-isomerase inhibitor irinotecan (Campto) toegediend aan een dosis van 180 mg/m² op dag 1 in combinatie met Elvorine 100mg/m² op dag 1 en 2, 5-Fluoro-Uracyl (5FU) bolus 400mg/m² op dag 1 en 2, 5FU continu infuus (1200mg/m²) via infusor op dag1 en 2 over 22uur. Op dag 3 wordt de infusor verwijderd door de thuisverpleging. Dit schema wordt 2 wekelijks herhaald. Mogelijke nevenwerkingen van campto zijn laattijdige diarree, nausea en braken, vermoeidheid, myelosuppressie, alopecia, anorexie en zeldzaam een acuut cholinerg syndroom. Mogelijke nevenwerkingen van 5-FU zijn diarree, nausea en braken, mucositis, anorexie, waterige ogen, smaakverlies, myelumsuppressie, nagelveranderingen, droge huid en zelden hand-voet syndroom', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('cisalimtaa', '* Alimta Cisplatinum In dit chemotherapieschema wordt cisplatinum (75 mg/m² d1), een alkylerend agens gecombineerd met het anti-metaboliet (anti-folaat) Alimta (500 mg/m² d1). Deze cyclus wordt om de drie weken herhaald. Ter preventie van de nevenwerkingen van Alimta dient co-medicatie met foliumzuur, vit B12 en medrol ingenomen te worden. Co-medicatie: - Foliumzuur 4 mg per dag (vanaf 1 week voor start tot 3 weken na beeindigen van de chemotherapie; in principe is een dagdosis van 1 mg voldoende). - Vitamine B12 IM te herhalen om de 9 weken (te starten 1 week voor de chemotherapie) - Corticosteroiden (medrol 32 mg 1 dag voor start 2x/d, dag van therapie 31s avonds nogmaals 32 mg; dag na therapie 2 x 32 mg; solumedrol 125 mg IV net voor start) Mogelijke nevenwerkingen van dit chemotherapie schema zijn nausea, braken, myelosuppressie (anemie, leucopenie en trombopenie), vermoeidheid, diarree, stomatitis, anorexie, neurotoxiciteit, ototoxiciteit, nefrotoxiciteit, alopecie (zelden) en jeukende huiduitslag (waarvoor preventie met corticoiden).', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('hunn', 'hydroureteronefrose ###', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('mtcff', 'Modified TCF In dit chemotherapieschema wordt op dag1 het alkylerend agens cisplatinum toegediend aan een dosis van 50 mg/m² voorafgegaan door prehydratatie. Eveneens wordt taxotere (Docetaxel) toegediend aan een dosis van 50mg/m² (dag1). Op dag 1 en 2 wordt het De Gramont schema toegediend. Hier bij wordt Elvorin 100 mg/m² op dag 1 en dag 2 toegediend, een bolus 5-Fluoro-Uracil (5FU) gegeven van 400 mg/m² op dag 1 en dag 2, en vervolgens via continu infuus 5-FU aan een dosis van 600 mg/m²/dag op dag 1 en dag 2. De derde dag wordt het pompje 5-FU afgeschakeld. Het hele schema cisplatinum - De Gramont wordt 2-wekelijks herhaald. Mogelijke nevenwerkingen van cisplatinum zijn nausea, braken, myelosuppressie (anemie, leucopenie en trombopenie), vermoeidheid, diarree, stomatitis, smaakveranderingen, anorexie, neurotoxiciteit, ototoxiciteit, nefrotoxiciteit en soms alopecie. Mogelijke nevenwerkingen van 5-FU zijn diarree, nausea en braken, mucositis, anorexie, waterige ogen, smaakverlies, myelumsuppressie, nagelveranderingen, droge huid en zelden hand-voet syndroom. Als nevenwerkingen van taxotere kunnen optreden: myelosuppressie en allergische reacties waarvoor premedicatie met steroiden en antihistaminica worden toegediend; stomatitis; perifere paresthesieën, myalgieën. Vochtretentie met toenemende oedemen en gewichtstijging, alsook soms ontstaan van ascites en pleuravocht, kan worden waargenomen naarmate de behandeling vordert. Totale alopecie treedt bijna altijd op. Tevens kunnen er zich huid- of nagelveranderingen voordoen. De gastro-intestinale tolerantie is meestal behoorlijk. Soms aanwezigheid van diaree. Er kan een toenemende vermoeidheid ontstaan. Comedicatie: Ter preventie van hypersensitiviteitsreacties dient patiënt 12u voor de start van de therapie Medrol 32 mg in te nemen. Dit wordt herhaald de ochtend van en de avond van de chemo en de ochtend na de chemotherapie.', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('rhh', 'rechterhypochonder ###', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('spoo', 'Uw ###-jarige patiënt werd gezien op de dienst spoedgevallen voor de afdeling IAL op ###. Wij bemerken het volgende: 1. ### Presentatie op spoed in kader van ###. Klinisch ###. Biochemisch ###. Radiografisch bemerken wij ###. Wij besluiten tot ###. Wij zien de patiënt graag terug op onderstaande datum. 2. ### Therapeutisch voorstel: ----------------------- ### Planning: --------- ###', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('folfirinoxx', '* FOLFIRINOX: In dit chemotherapieschema wordt de topo-isomerase inhibitor irinotecan (Campto) toegediend aan een dosis van 180 mg/m² om de 2 weken in combinatie met het alkylerend agens Oxaliplatin toegediend aan een dosis van 85mg/m² op dag 1 in combinatie met Elvorine 100mg/m² op dag 1 en 2, een 5-Fluoro-Uracyl (5-FU) bolus van 400mg/m² op dag 1 en 2 en een 5FU continu infuus (1200mg/m²) via infusor op dag1 en 2 over tweemaal 22uur. Op dag 3 wordt de infusor verwijderd door de thuisverpleging. Mogelijke nevenwerkingen van oxaliplatin zijn nausea, braken, myelosuppressie (anemie, leucopenie en trombopenie), diarree, mucositis, perifere neuropathie, vermoeidheid, anorexie en krampen (getriggerd door koude). Drinken van koude (en warme dranken) dient vermeden worden tijdens de toediening van de chemotherapie) Mogelijke nevenwerkingen van 5-FU zijn diarree, nausea en braken, mucositis, anorexie, waterige ogen, smaakverlies, myelumsuppressie, nagelveranderingen, droge huid en zelden hand-voet syndroom Mogelijke nevenwerkingen van campto zijn laattijdige diarree, nausea en braken, vermoeidheid, myelosuppressie, alopecia, anorexie en zeldzaam een acuut cholinerg syndroom.', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('fibroo', 'Fibrotest: ### (F3: 0.59-0.72, F3-F4: 0.73-0.74, F4: >0.75) APRI score: ### (F3: >1, F4: >1.6) FIB-4 score: ### (F3: >2.1, F3-F4: >3.25, F4: >3.85) Fibroscan dd. ###: ### kPa (SR ###%) (F3: >9.4 kPa, F4: >12.4 kPa)', '8798.0');
