INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('gerr', 'Uw ###-jarige patiënt werd heden opgenomen op de dienst Geriatie van ###/2016 t/m ###/2016. Wij bemerken het volgende: A. HUIDIGE PROBLEMATIEK 1. ###. Presentatie met ### sinds ###. Klinisch ###. Biochemisch ###. Radiografisch bemerken wij ###. Wij besluiten tot ###, waarvoor ###. Wij zien de patiënt terug op onderstaande datum. 2. ### 3. ### 4. ### B. COMORBIDITEITEN 1. ### 2. ### 3. ### C. GERIATRISCH PROFIEL 1. Geriatrische screening: - DNR-beleid: Geen DNR beleid tot op heden ### - MRSA: ###. - Biochemie: . Voldoende vitamine B12, foliumzuur en ijzer reserves ###. . Schildklierfunctie: ### . Nuchter glycemie: ### - Osteoporose: ### - MEDICAMENTEUS: . START medicatie: ### . STOP medicatie: ### 2. FUNCTIONEEL/COGNITIEF/SOCIAAL - Cognitief: ### - Functioneel: * Wassen/Kleden: ### * Marche: ### * Transfers: ### * Continentie/Toiletbezoek: ### * Voeding/slikproblematiek: ### - Sociaal: ### Therapeutisch voorstel: ----------------------- ### Planning: --------- ###', '8798.0');
