INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('bijnierr', 'Stress-schema corticoïden: -------------------------- ***Richtlijnen substitutie HC in geval van ziekte of heelkunde. Enkel voortzetten onderhoudsdosis bij korte procedures onder lokale verdoving. In andere omstandigheden (zie lijst hieronder) moeten volgende supplementen gegeven worden (boven onderhoudsdosis) - Mineure stress: 25 mg HC PO, IV, IM op dag van procedure (dag 1) - Matige stress: 50-75 mg HC IV of IM /dag1 afbouw over 1-2 d tot gewone dosis - Majeure stress: 2-3x 50mg HC IV of IM /dag 1 afbouw over 1-2 d tot gewone dosis. Bij optreden van hypotensie: verhoog tot 3x100mg IV HC/dag HC = hydrocortison (Solucortef voor i.v. of i.m. gebruik). Heelkundige of medische stress: voorbeelden van type procedure of ziekte - Mineur: herniorafie, knieoperatie, laparoscopische cholecystectomie, colonoscopie, milde koortsaandoening, milde tot matige misselijkheid of braken, gastro-enteritis - Matig: open cholecystectomie, rugoperatie, partiële colonresectie, heupvervanging, belangrijke febriele ziekte, pneumonie, ernstige gastro-enteritis - Majeur: pancreaticoduodenectomie, oesofagectomie, totale colectomie, darmperforatie, cardiopulmonale bypass, ileofemorale bypass', '8798.0');
