INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('fobtt', 'Geachte collega Wij zagen uw patiënt ### op de raadpleging maag- en darmziekten op ###. Huidige probleem: ----------------- We zien uw patiënte op raadpleging ikv positieve ifob Familiaal geen darmpoliepen of darmca. Huidige medicatie: ------------------ ### Bespreking en besluit: ---------------------- We weerhouden geen contra-indicaties voor uitvoeren van een coloscopie. Patiënt werd geïnformeerd over de mogelijkheid dat er significante poliepen ontdekt worden (30% kans bij pos FOB test) en poliepectomie dient uitgevoerd te worden. Hij/zij werd geïnformeerd over het mogelijk risico op bloeding en perforatie. Uitleg over de premedicatie werd gegeven. Patiënt stemde na de uitleg in met de procedure. Instructies rond voorbereiding werden uitgelegd en meegegeven. Coloscopie wordt gepland op ###. Er dienen geen medicatiewijzigingen te gebeuren. / Graag medicatie als volgt aan te passen: - Asaflow in primaire preventie: stop 5 dagen vooraf - Asaflow in secundaire preventie: Asaflow niet stoppen - Aggrenox (is normaal steeds in secundaire preventie): niet innemen ochtend van procedure - Plavix: stop 5 dagen op voorhand - Efient: stop 7 dagen op voorhand - Brilique: stop 5 dagen op voorhand - Ticlid: stop 5 dagen op voorhand - Marcoumar: stop 7 dagen voor de coloscopie, start LMWH zodra INR < 2 (geen Clexane geven avond voor en ochtend van het onderzoek) - Xarelto: stop 1-2 dagen op voorhand - Eliquis: stop 1-2 dagen op voorhand - Pradaxa: stop 2 dagen op voorhand Met collegiale hoogachting', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('sigmoo', 'Ppa : normaal. Voorbereiding d.m.v. lavement. BBPS :### Procedure tot op ### cm. Colon descendens en sigmoid : Normale mucosa met normaal vaatpatroon, normale haustraties en normale expansie. Rectum : Normale mucosa met normaal vaatpatroon, normale haustraties en normale expansie. Grondige inspectie van de rectale plooien. Normale retrovisie rectaal. Geen afwijkingen te weerhouden.', '8798.0');
