INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('rpll', 'Uw ###-jarige patiënt werd gezien op de raadpleging I.G. lever-, galblaas- en pancreasaandoeningen op ###. Wij bemerken het volgende: 1. ### Uw patiënt werd heden gezien in kader van ###. Klinisch ###. Biochemisch ###. Radiografisch bemerken wij ###. Wij besluiten tot ###. Wij zien de patiënt graag terug op onderstaande datum. 2. ### 3. ### Therapeutisch voorstel: ----------------------- ### Planning: --------- ###', '8798.0');
