INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('proctt', 'Medische voorgeschiedenis: -------------------------- ### Anamnese: --------- ### Proctologisch onderzoek: ------------------------- Onderzoek in genupectorale houding. Inspectie: ### PPA: normale tonus, niet pijnlijk, geen bloed op vingerling, geen massa''s ###. Anuscopie: normale mucosa, normale hemorroidale plexus ###. Besluit: --------- Uw patiënt werd gezien op de raadpleging Proctologie op ###. Beeld van ###. Therapievoorstel: ----------------- ### Planning: --------- ###', '8798.0');
