INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('ischiass', 'Ischiasis ---------------- Op basis van anamnese en klinisch onderzoek werden rode vlaggen (i.e. indicatoren van ernstige mechanische of niet-mechanische onderliggende pathologie) uitgesloten. De ischias is niet oncontroleerbaar en er is geen significante parese. We weten dat de evolutie van acute onverwikkelde ischias in de meerderheid van de patiënten een spontaan gunstig verloop kent. We weten ook dat radiologische onderzoeken meestal wel de oorzaak van de radiculaire compressie kunnen aantonen, maar dat dit in dit stadium geen invloed heeft op het te volgen beleid. De beste aanpak bestaat uit een zogenaamde actieve aanpak, waarin bedrust (langer dan zeven dagen) wordt vermeden, de patiënt zo snel mogelijk weer mobiel is en uiteraard rugbelasting vermijdt. Uw patiënt werd hierover mondeling en aan de hand van brochures (30De behandeling van acute lage rugpijn met zenuwwortelpijn31 en 30Houdings- en bewegingsadvies bij acute klachten aan rug of nek31) grondig ingelicht. Er werd pijnstilling voorgeschreven onder de vorm van paracetamol (maximum 4dd1 gram) en tramadol (2dd100 of 150mg). We schreven arbeidsongeschiktheid voor voor de duur van twee weken. We adviseerden patiënt om - als de last blijft bestaan - over één week de huisarts te bezoeken, zodat u het beleid kunt aansturen. We benadrukten dat uw patiënt geduld moet oefenen. Als de intensiteit van de ischias niet aanvaardbaar is, hebt u de mogelijkheid om snel toegang te krijgen tot de consultaties fysische geneeskunde binnen het zorgprogramma NTAAS van UZ Leuven via het prioritaire telefoonnummer 016 34 38 00. Als de ischias langer dan zes weken aansleept zonder neiging tot verbetering en u een advies omtrent een interventie wilt plannen, kunt u via hetzelfde prioritaire nummer ook toegang krijgen tot een snelle chirurgische consultatie op neurochirurgie of orthopedie binnen hetzelfde zorgprogramma. Uw patiënt werd ook geïnformeerd wat te doen bij het ontstaan van krachtvermindering of cauda equina symptomen (naar de spoedgevallendienst komen). Alle verdere informatie over de opvang en het verdere traject van acute wervelkolomproblemen in het zorgprogramma NTAAS van UZ Leuven vindt u op de website www.uzleuven.be/axiaalskelet.', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('cirrosee', 'Levercirrose (CHILD ### / MELD ###) - Secundair aan ###. Synthesecapaciteit: INR ### - Albumine ###. Als complicaties noteren we: - ### thrombopenie, ### splenomegalie. - Encefalopathie graad ###, waarvoor ###. - ### ascites, waarvoor ###. - ### nierfunctie. - ### slokdarmvarices - Geen evidentie voor HCC, ###.', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('remergg', 'In tussentijd werd ter behandeling van functionele dyspepsie type postprandial distress syndrome (FD-PDS)/epigastric pain syndrome (FD-EPS) reeds therapie met lage dosis mirtazapine (Remergon 15 g ''s avonds) gestart gedurende minstens 3 maanden (Tack J et al. Efficacy of Mirtazapine in Patients With Functional Dyspepsia and Weight Loss. Clin Gastroenterol Hepatol 2016).', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('cii', 'contraindicaties ###', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('ctmtt', '* Informatie CTMT Studie: In deze studie worden Ribociclib (inhibitor CDK4/cyclin D-1 en CDK6/cyclin-D3) en Trametinib (MEK-inhibitor) toegediend. Tijdens de eerste week is er monotherapie met Trametinib, tijdens de tweede week combinatie van Trametinib en Ribociclib en tijdens de derde week monotherapie met Ribociclib. Mogelijke nevenwerkingen van Ribociclib zijn: Anemie, vermoeidheid, neutropene koorts, trombopenie, rash, mucositis, QTc verlenging, hyponatriëmie, nausea en braken, levertoxiciteit Mogelijke nevenwerkingen van Trametinib zijn: Anemie, vermoeidheid, alopecia, rash, nausea, braken, hartfalen, HV syndroom, hypertensie, maagperforatie, colitis, folliculitis', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('bmss', '- Nivolumab: Dit betreft een PD1-inhibitor gevormd uit humaan immunoglobuline G4 (IgG4. Mogelijke bijwerkingen: gastrointestinale klachten (nausea/diarree/braken), dermale erupties, interstitiële pneumonitis en myalgiëen. In de BMS-studie zal dit middel worden toegediend q2w vanaf week 3, vanaf week 25 zal deze 4-wekelijks toegediend worden. Steeds in combinatie met daratumumab. - Daratumumab: Anti-CD38 recombinant immunoglobuline G1 (IgG1?) monoklonaal antilichaam. Tot voor kort vooral terugbetaald in kader van Multipel Myeloma. Mogelijke bijwerkingen: interferente met Directe Coombs, infusiereacties, atriumfibrillatie, bovenste luchtweginfecties en myelosuppressie. In de BMS-studie zal dit middel wekelijks worden toegediend t/m week 4, vanaf week 2 in combinatie met Nivolumab.', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('geii', 'Gastroenterologie ###', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('pmm', 'PM: (->zorg_laatste_bloeddruk<-)mmHg, (->zorg_laatste_hartslag<-)/min, (->zorg_laatste_temperatuur<-)°C, (->zorg_laatste_zuurstofsaturatie<-)%, pijnscore (->zorg_laatste_pijnscore_comfortschaal<-), (->zorg_laatste_gewicht<-)kg', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('pacll', 'Mogelijke nevenwerkingen van Paclitaxel zijn: myelosuppressie (voornamelijk neutropenie), allergische reacties (premedicatie met steroiden en antihistaminica), stomatitis, smaakverlies, anorexie, diarree, vermoeidheid, perifere paresthesieën en myalgieën en vochtretentie. In de regel treedt totale alopecie op. Ter preventie van hypersensitiviteitsreacties op Paclitaxel dient patiënt 12u voor de start van de therapie Dexamethasone 10mg (of medrol 32 mg) in te nemen. Dit wordt herhaald op de ochtend van dag 1 van de chemotherapie en de ochtend van dag 2 (dag na de chemotherapie). Op de avond voordien en de ochtend van dag 1 neemt patiënt ook Ceterizine 10mg in.', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('ramm', 'Ramucirumab is een recombinant humaan IgG1 monoklonale antistof dat specifiek bindt aan het extracellulaire domein van de VEGFR-2 met een hoge affiniteit. Deze antistof is een krachtige remmer van de binding tussen de VEGF ligand en de VEGFR-2, inhibeert de VEGF gestimuleerde activiteit van zowel de VEGFR-2 als de p44/p42 MAP kinasen en neutraliseert de VEGF geïnduceerde mitogenese van de endotheelcellen. De belangrijkste nevenwerkingen van dit geneesmiddel zowel op basis van de anti-angiogenense activiteit als van de mogelijke immunogeniciteit zijn de volgende: infuus-reacties, hypertensie, proteïnurie, thrombose, gastro-intestinale perforaties en bloedingen. De meest voorkomende nevenwerkingen (studies waarbij Ramucirumab in monotherapie werd gegeven) zijn: hoofdpijn, vermoeidheid, nausea, hypertensie en perifere oedemen.', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('her22', '* Trastuzumab (Herceptine) Mogelijke nevenwerkingen: Allergische reacties tijdens eerste toediening Cardiovasculair: cardiomyopathie, tachycardie, aritmie, vasodilatatie en hypotensie Gastro-intestinaal: diarree, buikpijn Pulmonaal: ademhalingsproblemen Andere: vermoeidheid, griepachtige verschijnselen', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('toff', 'Chemotherapie - TOF (Taxotere-Oxaliplatin-5FU) In dit chemotherapie schema wordt het alkylerend agens Oxaliplatin toegediend aan een dosis van 85mg/m² op dag 1 in combinatie met Elvorine 200mg/m² op dag 1 en 5-Fluoro-Uracyl (5FU) bolus 400mg/m² op dag 1 en vervolgens 5FU continu infuus (2400mg/m²) via infusor op dag1 over 48 uur. Eveneens wordt taxotere (Docetaxel) toegediend aan een dosis van 50mg/m² (dag1). Op dag 3 wordt de infusor verwijderd door de thuisverpleging. Dit schema wordt 2 wekelijks herhaald. Mogelijke nevenwerkingen van oxaliplatin zijn nausea, braken, myelosuppressie (anemie, leucopenie en trombopenie), diarree, mucositis, perifere neuropathie, vermoeidheid, anorexie en krampen (getriggerd door koude). Drinken van koude (en warme dranken) dient vermeden worden tijdens de toediening van de chemotherapie) Mogelijke nevenwerkingen van 5-FU zijn diarree, nausea en braken, mucositis, anorexie, waterige ogen, smaakverlies, myelumsuppressie, nagelveranderingen, droge huid en zelden hand-voet syndroom', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('fyss', 'Graag mobilisatie en amelioratie van het fysisch prestatievermogen ###', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('ercpp', 'ERCP: ### ----- ###', '8798.0');
