INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('condd', 'Condyloma acuminata peri- en intra-anaal waarvoor opstarten van Aldara 3x/week. ''s avonds aan te brengen en ''s morgens af te spoelen. Bij irritatie ev zinkoxyde zalf op andere dagen. Controle binnen 8-tal weken werd voorzien.', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('crypp', 'Afwisselend collargol (150mg suppo''s) en flagyl (500mg suppo''s) gedurende 20 dagen (2x10 stuks). Aanbrengen van cetavlex zalf. ###', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('fissuurr', 'Aldus sterk vermoeden van een (chronische) fissura ani: Start Diltiazemcreme 2% 2x/d lokaal, gevolgd door Cetavlex na elke stoelgang. Voldoende laxatie te voorzien, persen voorkomen. Zo ongunstige evolutie of persisterende klachten eventueel indicatie voor bijv. Botoxinjectie: controle te voorzien over 8-10w. Tevens indicatie voor totale coloscopie in tweede tijd gezien RBPA: te plannen buiten acute setting. Therapievoorstel: ----------------- Start Diltiazem creme 2% 2x/d Start cetavlex na elke stoelgang Voldoende laxatie: Movicol Planning: --------- Controle na 8 weken ter controle fissuur en zo nodig bijv. Botoxinjectie. Tevens indicatie voor totale coloscopie in tweede tijd gezien RBPA: te plannen buiten acute setting. ###', '8798.0');
