INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('conss', 'Uw ###-jarige patiënt werd in consult gezien voor de dienst I.G. lever-, galblaas- en pancreasaandoeningen op ###. Consultvraag: ------------- ### Medische voorgeschiedenis: -------------------------- Technische onderzoeken: ----------------------- Labo: cfr bijlage ----- Te vermelden: ### BESPREKING EN BESLUIT ===================== Uw ###-jarige patiënt werd in consult gezien voor de dienst I.G. lever-, galblaas- en pancreasaandoeningen op ###. 1. ### Therapeutisch voorstel: ----------------------- ### Planning: --------- ###', '8798.0');
