INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('cetuxx', 'Therapievoorstel dermatologie: - Minocycline 100 mg 2x/d verder - Op op puistjes gelaat en borst: ''Metronidazole 2% in cetomacrogolcreme ad 100%'' 2 x per dag - Op lippen: Fucidinezalf 2 x per dag Aquaphor Eucerin meerdere malen per dag tussendoor ter bescherming - Schaamstreek: 3x per week wassen met isobetadine zeep en lokaal cetavlex crème aanbrengen', '8798.0');
