INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('gybb', 'SLOKDARM De slokdarm is normaal. De top van de maagplooien ligt op 40 cm. MAAG Kleine maagpouch post-GYB. JEJUNUM Rustige anastomose en blinde lis. Normale efferente lis. BIOPSIES Er werden geen biopsies genomen. BESLUIT ======= - Normale status na gastric bypass.', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('opn', 'Uw ###-jarige patiënt werd gezien opgenomen op de dienst maag-, darm- en leverziekten op ###. Wij bemerken het volgende: 1. ### Presentatie op spoed in kader van ###. Klinisch ###. Biochemisch ###. Radiografisch bemerken wij ###. Wij besluiten tot ###. Wij zien de patiënt graag terug op onderstaande datum. 2. ### Therapeutisch voorstel: ----------------------- ### Planning: --------- ###', '8798.0');
