INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('isoo', 'Relatieve isolatiemaatregelen in de thuissituatie werden uitgelegd (ook voor familie/gezin!). Quarantainemaatregelen te continueren tot minstens 7d na resolutie van klachten. Bij evolutieve dyspnee: hercontactname te voorzien.', '8798.0');
