INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('avv', 'Bevacizumab (Avastin) Avastin (bevacizumab) is een monoclonaal antistof gericht tegen VEGF (Vascular Endothelial Growth Factor). Hierdoor wordt neo-angiogenese geremd. Het wordt toegediend aan een dosis van 5mg/kg om de 2 weken. Frequente nevenwerkingen zijn arteriële hypertensie en proteïnurie (evt. zelfs nefrotisch syndroom). Minder frequente nevenwerkingen zijn: overgevoeligheidsreacties, thrombo-embolische fenomenen, bloedingsdiathese, vertraagde wondheling, heesheid, osteonecrose van de kaak en gastrointestinale tractus perforaties. De halfwaardetijd van Avastin bedraagt ongeveer 2 à 3 weken. Er wordt dan ook een interval van 4 à 6 weken aangeraden tussen Avastin toediening en electief heelkundig ingrijpen.', '8798.0');
