INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('hpe', '- APO: Hp positief. Indicatie voor opstarten van eradicatietherapie. Volgens de laatste Belgische consensusrichtlijnen (2023) bestaat de empirische eradicatietherapie uit ?quadruple therapie?, gezien de toenemende resistentie aan clarithromycine. * Volgend schema wordt aanbevolen indien geen penicilline-allergie bestaat, gedurende 14 dagen: - PPI 2x/dag: best esomeprazole 2x40 mg - Clarithromycine 2x500 mg per dag - Amoxicilline 2x1 g per dag - Metronidazole 3x500 mg per dag * Bij penicilline-allergie, of bij falen van een eerste lijn, is een quadruple therapie op basis van bismuth aangewezen, gedurende 10 dagen: - PPI 2x/dag: esomeprazole 2x40 mg - Tryplera® 4x3 capsules per dag (in te nemen na elke maaltijd en voor het slapengaan) * Magistraal kan Tryplera® voorgeschreven worden als volgt: - Bismuthsubgallaat 4x300 mg per dag - Tetracycline 3x500 mg per dag - Metronidazole 3x500 mg per dag * De ?triple therapie?, zijnde clarithromycine, amoxicilline en high dose PPI, kan ook nog worden gebruikt indien er een bewezen gevoeligheid bestaat voor clarithromycine op basis van antibiogram. Bij falen van twee lijnen therapie dient een gevoeligheidsbepaling via antibiogram te gebeuren. * Idealiter wordt 6 weken na stoppen van de antibiotica en na een onderbreking van PPI-therapie van 2 weken de effectiviteit van de eradicatie getest via een bepaling van het feces Ag voor H. Pylori (stoelgangsstaal).', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('amb', 'antimicrobiële therapie', '8798.0');
