INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('euss', 'Vanuit maagpositie: Visualisatie van respectievelijk, tr.coeliacus, AMS en confluens. Identificatie van de pancreas: De wirsung kan tot distaal gevolgd worden en heeft een ### normale diameter. ### galblaas. Normaal ### leverparenchym. Bulbair: Normale pancreaskop en portale triade. DII: Geen distale CDL gevisualiseerd. Geen toegevoegde massa''s op dit onderzoek', '8798.0');
