INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('leverr', 'Consult gastro-enterologie wegens milde leverfunctiestoornissen. Eerder gemengde leverfunctiestoornissen met milde ALT-stijging ( ### ) en alkalische fosfatasen ( ### U/l). Echografie bleek negatief ###. Differentieel diagnostisch: 1. DILI (Drug Induced Liver Injury): Augmentin? Tavanic? 2. Parainfectieus Te voorzien: - Virale serologie: HBV, HAV, HCV, CMV & EBV. - autoimmune serologie met anti-mitochondriale antistoffen, gladde-spiercelantistoffen en ANF. Therapievoorstel: Voorstel tot switch naar Tavanic-Flagyl (quasi vergelijkbare dekking vs. Augmentin). Dagelijks labo met leverset en stolling.', '8798.0');
