INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('micc', '- APO: microscopische colitis, type collageneuze colitis. - Voorstel tot opstart budenofalk 3x3mg, af te bouwen per maand naar 2x3mg/d, 1x3mg en stop. - Graag verwijzing naar de raadpleging zo persisterende diarree en/of snel recidief.', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('laxx', 'Voorstel tot: - dagelijkse inname van Movicol (1-2-3 zakjes per dag, naargelang effect). - Laxoberon 15 druppels zo > 48h geen stoelgang. - Bij persisterende/invaliderende last: verwijzing naar de raadpleging voor oa. Rx colpocystodefecografie en Rx transit.', '8798.0');
