INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('proctt', 'Huidig probleem: ### Proctologisch onderzoek: Inspectie: normaal ###. PPA: ### normale tonus, geen massa''s. Ano-rectoscopie: ###. Besluit: Uw ###-jarige patient werd gezien op de raadpleging Proctologie. Wij bemerken het volgende: ### Met collegiale groeten, DR MICHIEL BRONSWIJK Internist Gastro-Enteroloog', '8798.0');
