INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('ucc', 'Mayo-score: ### 0: normaal. 1: Mild: mild erythema, mild friability, discrete loss of vascular pattern. 2: Moderate: friablitity, erosios, erythema, loss of vascular pattern. 3: Severe: spontaneous bleeding, ulceration. UCEIS: ### Vascular pattern: Normaal (0), Patchy (1), Obliteration (2). Bleeding: None (0), Mucosal (1), Luminal mild (2), Moderate/Severe (3) Erosions: None (0), Erosions (1), Ulcers (2), Deep Ulcers (3).', '8798.0');
