INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('ge', 'Aldus beeld van acuut ontstane vomitus en nausea, differentieel diagnostisch meest verdacht voor gastroenteritis, waarvoor IV vocht en antiemetica. Snelle resolutie van de klachten. Geen noodzaak tot verdere follow up. Mogelijkheid van postinfectieuze IBS werd uitgelegd.', '8798.0');
