INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('krrr', 'Uw patiënt werd besproken op de krans gastro-enterologie. Informed Consent: De patiënt/vertegenwoordiger van de patiënt werd geïnformeerd over de behandeling/ingreep/medische procedure, heeft de verstrekte informatie begrepen, mogelijkheid gehad om vragen te stellen, en heeft toegestemd met de behandeling/ingreep/medische procedure. Medische Voorgeschiedenis: ### Huidig Probleem: ### Technisch onderzoek: - Labo: ### - Echo abdomen: ### - ### BESPREKING EN BESLUIT: Uw patiënt werd besproken op de krans gastro-enterologie. Als problemen weerhouden we: ### Dr. M. Bronswijk ASO Gastroenterologie Namens de Internist-gastroenterologen, Dr.G.Van Olmen Dr.P.Christiaens Dr.V.Moons Dr.P.Bossuyt Dr. P-J.Cuyle Dr. S.Carton Dr. L. Pouillon.', '8798.0');
