INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('consultt', 'Uw ###-jarige patient met voorgeschiedenis van ### werd op de raadpleging Maag-, darm- en leverziekten gezien. Wij bemerken het volgende: ### Therapievoorstel: Met collegiale groeten, DR MICHIEL BRONSWIJK Internist Gastro-Enteroloog', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('ercpp', 'Inbrengen van de endoscoop tot voor de papil van vater. De papil komt normaal voor. Vlotte cannulatie van de choledochus. - Aanwezigheid van distale choledocholithiasis. - Aansluitende brede papillotomie. - Meerdere ballonsweeps met extractie van verschillende (>2) choledocholithiasen. - Occlusiecholangiogram toont geen residuele stenen. Goede afloop. BESLUIT: - Papillotomie en ballonextractie van meerdere choledocholithiasen. - CCE best aansluitende te voorzien aan deze opname ter preventie van recidief (Noel et al. HPB 2018). Met vriendelijke groeten, DR MICHIEL BRONSWIJK Internist Gastro-Enteroloog', '8798.0');
