INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('rutgg', 'Rutgeertsscore ### Rutgeertsscore: i0 No lesions in the distal ileum i1 <= 5 apthous lesions i2a lesions confined to ileocolonic anastomosis i2b > 5 apthous lesions with normal mucosa between the lesions, or skip areas of larger lesions (with or without anastomotic lesions) i3 Diffuse apthous ileitis with diffusely inflamed mucosa i4 Diffuse inflammation with already larger ulcers, nodules, and / or narrowing', '8798.0');
