INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('dormm', '5 mg midazolam + 0.5mg rapifen.', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('cockk', '5 mg midazolam + 50mg pethidine + 2 amp DHBP.', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('scleroo', 'Intermittent RBPA, hoogstwaarschijnlijk door hemorroidaal lijden. Heden eerste sclerotherapiesessie. In toto zullen er 2-3 sessie(s) nodig zijn. Voor- en nadelen t.o.v. ligaturen werden aan de patient uitgelegd. Makkelijke stoelgang na te streven in de thuissituatie, alsook vermijden van persen. Herevaluatie over 4-6 weken.', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('kozz', 'Algemeen: Comfortabele patiënt. Euvolemisch. Cor: S1S2, RR. Geen souffles of bijgeluiden. Pulm: VAG Bilateraal, geen bijgeluiden. Abd: Soepel, pijnvrij. Normoperistalsis &-tympaan. Geen organomegalie. Ledematen: Geen oedemen. Sterke perifere pulsaties. Derm: Geen afwijkingen. Vrije klierstreken. NKO: geen adenopathieen. Pharynx: nl. Neuro: PEARL, craniale zenuwen ok. Bilateraal symm. kracht in O- & BL.', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('racc', 'Regular arrangement of collecting venules: ###.', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('stentss', '------------------------------------------------------------ Volgende prothese(n) werd(en) geplaatst: ### met lotnummer ### ### met lotnummer ### De bijhorende implantaatkaart(en) (conform het KB van 27.09.2020) werd(en) vervolledigd en met patiënt meegegeven. -------------------------------------------------------------', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('lgdd', 'lage graad dysplasie ###', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('hgdd', 'hoge graad dysplasie ###', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('zenkerr', 'De reden voor het uitvoeren van het onderzoek was Zenker. Premedicatie: 5 mg midazolam + 50mg pethidine + 2 amp DHBP. Zenkerdivertikel met brede zenkerbrug. Selectieve cannulatie van slokdarm tot D3. Plaatsen van voerdraad waarover sonde. Visualiseren van zenkerbrug met cap. Partieel doorhalen van de Zenkerbrug met SB knife. Vlotte passage nadien. Geen lokale complicaties of subcutaan emfyseem. De cardia valt samen met de diafragma-pijlers en is normaal. De mucosa,plooien en expansie van de fundus en het corpus van de maag vertonen geen afwijkingen. Het antrum is intact. Er is een scherpe angulus. De pyloor is goed doorgankelijk. De bulbus vertoont geen letsels. Het tweede en derde deel van het duodenum zijn normaal. BESLUIT: ======== Flexibele myotomie voor Zenkerdivertikel. Aandachtspunten voor op zaal: - Parameters volgen - NPO - Morgen RX hals + thorax. - Maagsonde nooit herplaatsen. - Ambulate controle-gastroscopie na 1 maand bij mij.', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('mott', 'Motilium 10mg 10min voor de maaltijd 3x/d. ###', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('allergiee', 'Wat betreft de specifieke voedings-gerelateerde IgG''s dewelke biochemisch werden vastgesteld, lijkt het correllaat - ook wetenschappelijk gezien - soms moeilijk te maken. Hetgeen ook hier het geval lijkt, gezien exclusie van deze middelen (ei, tomaat etc) niet tot betering leidde. Zo bovenstaande investigaties geen afwijkingen tonen en proeftherapie weinig soelaas brengt kan een FODMAP-dieet wel geprobeerd worden. Door initiele exclusie en vervolgens selectieve inclusie van voedingsmiddelen kan mogelijks wel uitlokkende factoren geidentificeerd worden. Nadeel: redelijk intensief zo goed uitgevoerd.', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('ssaa', 'sessile serrated adenoma (SSA) ###', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('edgee', 'Introductie van de EUS-scope tot in de maagpouch. Visualisatie van gastric remnant rond de gastroenterische anastomose. Punctie met 19G-naald van ''sand dollar''-sign. Contrastopacificatie bevestigde intragastrische positie. Instillatie van ###ml NaCl 0.9%. Switch naar 20mm Hot-Axios platform: onverwikkelde plaatsing met vorming van gastro-gastrostomie.', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('jeukk', 'Wat betreft anale jeuk: - Vochtige wc doekjes gebruiken - Zo onvoldoende: applicatie van Zinkoxidezalf/vette witte zalf na de stoelgang - Zo nog onvoldoende effect na enkele weken: evt. Questran 1 zakje per dag (enkele weken te proberen. ###', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('annickk', 'Dr. Annick Moens, ASO Gastroenterologie O.s.v.', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('radd', 'Vlotte progressie tot in de bulbus. Goed zicht op CBD, cysticusorigo en intrapancreatisch verloop. CBD diameter: ###mm, ###. MPD lijkt normaal, met ###mm-diameter. Normale pancreaskop. Vanuit DII normale ampulla zonder evidentie voor lithiasen. Galblaas: ###.', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('fluctioo', 'Beeld van gethromboseerde externe hemorroid. Voorstel tot: - Laxatie - Daflon 6x/d gedurende 7 dagen - Coseanal (corticoidvrij) of alternatief: Scheriproct gedurende enkele dagen bij pijn.', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('fukk', 'Fukuoka classification: ---------------------- branch duct IPMN (BD-IPMN) cyst >5 mm communicating with main duct main duct IPMN (MD-IPMN) higher frequency of malignancy dilatation of the main duct > 5 mm without other cause for obstruction 5-9 mm: "worrisome feature" ?10 mm: "high-risk stigmata" mixed-type IPMN: appears like an advanced branch duct IPMN with main pancreatic duct dilatation (>5 mm) higher frequency of malignancy, similar to the main duct type High-risk stigmata: ------------------ enhancing solid component >5 mm: strongest association with malignant IPMN main pancreatic duct >10 mm obstructive jaundice Worrisome features: ------------------ cyst >3 cm thickened and enhancing cyst wall enhancing mural nodule 5 mm in two years elevated Ca19-9 Treatment and prognosis: ----------------------- resection: all main duct IPMNs all other IPMNs with high-risk stigmata all mucinous cystic neoplasms endoscopic ultrasound (EUS): cysts with worrisome features all cysts >3 cm without worrisome features if inconclusive, then close surveillance with alternating MRI and EUS every 3-6 months strongly consider surgery in young patients Cyst fluid analysis is optional in a center with expertise in EUS fine-needle aspiration. Surveillance: ------------ Optimal imaging surveillance strategies for suspected BD-IPMNs', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('Lamss', 'lumen-apposing metal stent (LAMS) ###', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('rosemontt', 'Rosemont classificatie ---------------------- Hyperechoic foci with shadowing Major A ### Lobularity Major A ### A. With honeycombing Major B ### B. Without honeycombing Minor ### Noncontiguous lobules Minor ### Hyperchoic foci without shadowing Minor ### Cysts Minor ### Stranding Minor ### MPD calculi Major A ### Irregular MPD Minor ### Dilated side branches Minor ### MPD dilation 3.5-mm body >1.5-mm tail Minor ### Hyperechoic MPD margin Minor ### I. Consistent with CP A. 1 major A feature >2 minor features B. 1 major A feature + major B feature C. 2 major A features II. Suggestive of CPy A. 1 major A feature 2 minor features C. >4 minor features (any) III. Indeterminate for CPy A. 3 to 4 minor features, no major features B. major B feature alone or with', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('neurolysee', 'Opzoeken aorta en truncus coeliacus links. Aanprikken van de zone rond de coeliacus met 19G naald. Na aspiratie, injectie van 5ml Marcaine 0.5% en 10 ml Ethanol 96%. Herhalen van de procedure rechts.', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('aldaraa', 'Opstart van Aldara: - 3x/week aanbrengen (bijv. voor slapen gaan), afwassen nadien. - Vaseline op de niet-aangetaste huid ter bescherming - Minstens 4-6 weken (max. 16 weken). - Controle in januari - Attest werd opgestuurd', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('postopp', 'Vlotte introductie van de EUS scoop tot in de maag. Identificatie van collectie gelegen ###, afmetingen ###mm. Typische etterdensiteit. Punctie met 19G-naald: confirmatie. Staalname voor microbiologie. Vervolgens doorvoeren van guidewire tot in de collectie. Uitwisselen voor 6Fr, waarmee traject bestendigd wordt. Ballondilatatie van traject tot 6mm, gevolgd door finale plaatsing van ###Fr x ###cm double pigtailstent (###).', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('eftrr', 'Mogelijke voor- en nadelen werden met de patient besproken, waarbij heelkunde en surveillance steeds een valabele optie zijn. Doch gezien bovenstaande problematiek lijkt eFTR de meest optimale aanpak. Risico''s van (laattijdige) perforatie (in 2.7%) werden met de patient besproken, deze risico''s zijn weinig frequent en tevens te beperken door systematische laxatie postprocedureel. Andere complicaties zoals bijv. bloeding zien wij eigenlijk niet, dit door het hemostatisch effect van de ''over-the-scope''-clip. R0-resectie ratio nadert bij dit soort letsels de 90% en is afhankelijk van de afmetingen van het te reseceren letsel (idealiter', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('eushgg', 'Visualisatie van gedilateerde (###mm) galwegen in segment ###. Punctie met 19G naald: confirmatie van intraductale positie door aspiratie van gal en contrastinjectie respectievelijk. Doorvoeren van guidewire tot ###. Bestendiging van traject met 6Fr cystotoom. Finaal plaatsing van ###x###mm ###-covered SEMS.', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('lamss', 'lumen-apposing metal stent ###', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('postopp', 'Evaluatie met liniaire EUS: identificatie van collectie gelokaliseerd ### met ###densiteit. Punctie met 19G naald: bevestiging van ###. Doorvoeren van guidewire, gevolgd door bestendiging van traject met 6Fr cystotoom. Ballondilatatie van traject tot ###mm. Finaal plaatsing van ###Fr x ###cm double pigtailstent (###).', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('apcc', 'argon plasma coagulatie (APC) ###', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('gbdd', 'Vlotte introductie van de EUS scoop tot in de bulbus. T.h.v. ### wand identificatie van hydroptische galblaas met etterdensiteiten en sludge/stenen. Introductie van Hot-Axios electrocautery-enhanced LAMS (###x###). Sequentiële deployment onder zicht. Spontane afvloei van gal en etter. Confirmatie van goede plaatsing visueel, echoendoscopisch en fluoroscopisch met contrastinjectie.', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('studiee', '******** Patient werd geincludeerd in een ''Multicentrische databank van prospectief verzamelde beelden en video''s van colorectale laesies ter ontwikkeling van artificiële intelligentie voor inschatting van submucosale diepte van invasie''. Lokale onderzoeker: dr. M. Bronswijk. Centrale opdrachtgever: UZ Leuven, Herestraat 49, 3000 Leuven, België (s65253 & s65254). Dit betreft het studie waarbij we in verschillende europese centra (multicentrisch) beelden en corresponderende histologische informatie wensen te verzamelen op een prospectieve wijze. Dit houdt in dat de verzameling van beelden nieuw is en gebeurd i.k.v. een nog niet verrichte procedure. De desbetreffende procedure zal een coloscopisch onderzoek betreffen tijdens dewelke we beelden wensen te maken van grote darmpoliepen (colorectale laesies). Deze beelden zullen later gebruikt worden voor ontwikkeling van een nieuwe computersoftware (artificiële intelligentie) die in staat is om de histologie (microscopische karakteristieken) en uitgebreidheid van invasie in de darmwand (submucosale invasie) zelf te gaan voorspellen. ********', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('zenkerr', 'Zenkerdivertikel met brede zenkerbrug. Selectieve cannulatie van slokdarm tot D3. Plaatsen van voerdraad waarover sonde. Visualiseren van zenkerbrug met cap. Partieel doorhalen van de Zenkerbrug met SB-knife junior met silcospray op de punt. BESLUIT: ======= Flexibele myotomie voor Zenkerdivertikel. Aandachtspunten: ---------------- Parameters volgen NPO Morgen RX hals + thorax. Maagsonde nooit herplaatsen. Ambulate controle-gastroscopie over 1 maand is aangewezen.', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('esgee', 'ESGE guidelines ### update 2020', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('refluxx', 'Conservatieve maatregelen bij reflux: * Voeding: - Meerdere kleine porties per dag zijn te verkiezen boven grote porties. - Goed kauwen op elke hap. - Voldoende drinken. Vezelrijke voeding. - Vermijden koffie, alcohol, fruitsap en bruisende dranken. - Geen vettige maaltijden ''s avonds. - Laat 3u tussen de laatste maaltijd en het slapengaan. - Mijden van ajuin, look, citrusvruchten, pikante kruiden en chocolade. * Algemene maatregelen: - Rookstop. - Overgewicht te mijden. - Stress te mijden. - Mijden van ontstekingsremmers. - Mijden van het dragen van te strakke kledij. - Hoofdeinde van het bed 15 cm hoger plaatsen. - Door de knieën buigen om iets op te rapen.', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('spasmomenn', 'Gezien stoelgang onder controle momenteel, voorstel tot opstart Spasmomen 3x40mg minstens 6-8 weken. Zo betering: nog enkele maanden continueren gezien protectief effect op termijn. ###', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('resoo', 'Zo onvoldoende evt. via de huisarts opstart Resolor 1mg/d, zo nodig op te drijven naar 2mg (CAVE transiente hoofdpijn).', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('rfaa', 'Radiofrequente ablatie (RFA) van Barrett werd uitgevoerd, circulaire RFA met HALO 90 thv GEJ, gevolgd door focale - gerichte RFA van residuele uitlopers. Tweemalige RFA, abrasie en cleanen met cap, gevolgd door opnieuw RFA. ### & ### hits. 2x2 15J. BESLUIT: ======= - Succesvolle RFA van niet-circulaire Barrett (C: ###. M: ###) met bewezen hooggradige dysplasie. Verdere adviezen: - Nuchter tot morgen. Labo te voorzien. - PPI 2x40mg reeds vandaag, te continueren tot controle. - Analgetica naar nood. - Controlegastroscopie over 3 maanden.', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('pexactt', 'Endoscopische transluminiscentie van de buikwand vanuit de maag. Locale verdoving met Xylocaine 1 % zonder adrenaline. Aanprikken van de maag met Pexact device, met aanleg van gastropexie. Tussen beiden draden incisie en insertie van trocar. Uitwisselen voor 15Fr ballonsonde, 5cc aqua in ballon. Wegpeelen van trocar.', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('prurituss', 'Voorstel tot pragmatische aanpak met: - Vochtige toiletdoekjes - Zinkoxidecreme applicatie ná elke stoelgang - Zo onvoldoende betering: Questran 1 zakje per dag (minstens 4-6 weken), evt. nog op te drijven. - Zo alsnog persisterende last: evt. Capsaicinezalf te overwegen (CAVE nogal kostelijk)', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('elastoo', 'Liver fibrosis classification SW Elastography kPa range SW Elastography m/sec range F0-F1: Absent or mild fibrosis < 8.27 < 1.66 F2: Significant fibrosis 8.27 - 9.40 1.66 - 1.77 F3: Severe fibrosis 9.40 - 11.88 1.77 - 1.99 F4: Cirrhosis > 11.88 > 1.99', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('advv', 'Verdere adviezen: - Nuchter tot nader order. Morgen labo. - PPI 2x40mg reeds vandaag. - Te monitoren voor nabloeding. - Controlegastroscopie te voorzien over 3 maanden (cfr KWS). - Eventuele anticoagulatie pas herstarten na 72h. ###', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('gabyy', 'MAAG Status na gastric bypass. EFFERENTE LIS Normale mucosa, rustige anastomose. ###', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('gooo', 'gastric outlet obstructie ###', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('diprii', 'propofolsedatie.', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('dzz', 'dagziekenhuis ###', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('buriedd', 'Extern doorvoeren van guidewire doorheen afgeknipte buried PEG sonde naar het maaglumen. Endoscopisch oppikken van de voerdraad met lus. Over voerdraad invoeren van TTS ballon doorhhen lumen van de bumper tot extern. Gericht opblazen van de ballon als "anker". Transorale extractie van oude PEG sonde. Herplaatsing via de guidewire van nieuwe PEG-sonde. Bijkomende plaatsing van nieuwe jejunale extensie diep in jejunum. BESLUIT: ======= Succesvolle endoscopische behandeling van buried bumper via ''BDP-method'' (M. Maly, M. Bronswijk, P. Christiaens, et al. AGEB 2023). Bij nieuwe buried bumper syndroom: herplannen onder anesthesieslot met dan tevens volledig nieuw traject (cfr recidiverend karakter).', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('leferee', '1/ maximum diameter MPD: ----------------------- head: ### mm body: ### mm tail: ### mm 2/ cystic focal lesion (if>3 cysts: only 3 largest): --------------------------------------------------- location (head/body/tail) ### maximum bidimenstionla diameter: ### mm communication with the MPD (y/n): ### septa within the cyst (y/n): ### mural nodule within the cyst: (y/n): ### if yes colour doppler signal in nodule (y/n/NA): ### 3/ soid lesion: -------------- location (head/body/tail) ### maximum bidimenstionla diameter: ### mm 4/ abrupt >50% MPD diameter change with distal atrophy (y/n): ### measurement setting ### Hz head measured from the top of the bulb body measured from the stomach at the leverl of the aorta tail measured from the stomach at the leverl of the left kidney', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('rybb', 'Start Rybelsus - week 1-4: 3 mg 1×/d - week 5-8: 7 mg 1×/d - week 9-12: 14 mg 1×/d, controle nadien.', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('armaa', 'ARMA (antireflux mucosale ablatie)', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('voltt', 'Voltarensuppo.', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('ssedgee', 'EUS-guided gastro-gastrostomie: Introductie van de EUS-scope tot in de maagpouch. Visualisatie van gastric remnant rond de gastroenterische anastomose. Punctie met 19G-naald van ''sand dollar''-sign. Contrastopacificatie bevestigde intragastrische positie. Instillatie van ###ml NaCl 0.9%. Switch naar 20mm Hot-Axios platform: onverwikkelde plaatsing met vorming van gastro-gastrostomie. Gastroscoop: Plaatsing van Ovesco Stentfix device. ERCP-scoop: Passage doorheen LAMS met 180-duodenoscoop. Stapsgewijze fluoroscopie-geleide passage transpylorisch tot prepapillair. ###', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('barrettt', '----------------------------------------------------------------------------------------------------- Barrettsurveillance adviezen o.b.v. ESGE guidelines update 2023: * Diagnose Barrett: aanwezigheid van minstens ''intestinale metaplasie'' noodzakelijk. * Proton pomp inhibitor: 40mg/d levenslang voor alle patienten met Barrett, geen dosisreductie! * Surveillanceintervallen: - Barrettslokdarm 75 jaar of bij verwachte overleving', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('laagg', 'Gezien laag risicoprofiel voorstel tot hernemen iFOB-screening (evt. via u) of controlecoloscopie over 10 jaar (zie hieronder).', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('besluitt', 'BESLUIT: =======', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('armaaa', 'Ik besprak heden ARMA (antireflux mucosale ablatie) met de patient. Hierbij wordt er met argon plasma coagulatie (APC) de gastro-oesofagale junctie geableerd, waarbij er een gunstige evolutie qua QoL en zuurexpositie. In toto kan er in 60-75% van de patienten de PPI gestopt worden. Risico''s (bloeding, strictuur) werden met de patient besproken. De patiënt/vertegenwoordiger van de patiënt werd geïnformeerd over de behandeling, heeft de verstrekte informatie begrepen, mogelijkheid gehad om vragen te stellen, en heeft toegestemd met de behandeling. Procedure zal via nachtje opname gepland worden.', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('blockk', 'Echo-endoscopisch opzoeken van de aorta en zijn aftakkingen, tr.coeliacus, AMS. Punctie met 19G naald en diepe juxta-aortale injectie van 5cc Ropivacaine 7.5%, 5cc ethanol 97% en vervolgens 5cc Ropivacaine 7.5%. Vervolgens contralateraal herhalen van deze sequentie t.h.v. para-aortale plexus volgens Sakamoto et al. (AGJ 2010). Geen lokale complicaties. BESLUIT : --------- Succesvolle EUS-guided para-aortaal block i.k.v. refractaire pijnklachten. Verdere adviezen: - Ruime cristalloiden toediening in kader van potentiele transiente bloeddrukschommelingen.', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('ibsadviess', 'Indien het calprotectine verhoogd is, dient aangevuld te worden met een ileocoloscopie om IBD uit te sluiten. Indien het calprotectine normaal is, kan verder behandeld worden als een prikkelbaar darmsyndroom, waarbij ik zou voorstellen om te starten met Gelsectan 2x 1/dag als medicamenteuze optie en het dieet te blijven volgen volgens de FODMAP principes met specifieke aandacht voor eventueel opgespoorde intoleranties in de aanvullende ademtesten.', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('spigelmann', 'Adviezen: - Voorstel tot controlelabo jaarlijks met oa. leverset. - Echo schildklier nog te voorzien (correllaat met FAP). - Screening leverletsels: ### Spigelman criteria: ### + ### + ### + ### ------------------------------------- Punten 1 2 3 Poliep aantal 1-4 5-20 >20 Poliep grootte 1-4 5-10 >10 Dysplasie Licht Middelmatig Ernstig Histologie Tubulous Tubulo-villous Villous Classification: no polyp: stage 0; 1 to 4 points: stage I; 5 to 6 points: stage II; 7 to 8 points: stage III; 9 to 12 points: stage IV Stadium 0 geen poliepen; controle na 4 jaar Stadium I 1-4 tubulaire adenomen, 1-4mm; controle na 2-3 jaar Stadium II 5-19 tubulaire adenomen, 5-9mm; controle na 2-3 jaar Stadium III < 20 adenomen, of minstens 1 cm; controle na 6-12 maand Stadium IV uitgesproken polyposis, ernstige dysplasie; heelkunde / frequente endoscopische followendoscopische of chirurgische resectie', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('arma', 'DIAGNOSTISCHE EN THERAPEUTISCHE PROCEDURES Er werd een endoscopische ablatie uitgevoerd met argon plasma coagulatie (APC). Hoefijzervormige anti-reflux mucosale ablatie volgens Inoue et al. EIO 2020: Forced, Effect 1 - 80w. Overlaten van 1cm mucosale brug ter preventie van stenose. BESLUIT: ======= - Succesvolle ARMA (antireflux mucosale ablatie). Verdere adviezen: - Zo pijnvrij: deze avond dranken/vloeistoffen. - PPI 2x40mg reeds vandaag, nadien 1x40mg gedurende 1 maand. - Controlegastroscopie te voorzien over 1 maand (cfr KWS). - Eventuele anticoagulatie pas herstarten na 72h.', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('eusgee', 'Gastroscoop: Passage tot voorbij ### strictuur: opvoeren van guidewire met diagnostische catheter tot voorbij Treitz. Uitwisselen voor 7Fr nasobiliaire catheter, uittrekken van guidewire met achterlaten catheter. Extractie gastroscoop. EUS: Voorzichtige introductie van EUS scoop langs nasobiliaire catheter. Op geleide van fluoroscopie en EUS beeld identificatie van gedilateerde dundarmlis. Confirmatie juiste positie door identificatie van inliggende catheter. Vervolgens vlotte plaatsing van 20x10mm Hot-Axios LAMS. Confirmatie goede positie door zowel EUS-beeld als fluoroscopisch. BESLUIT: ======= - Succesvolle EUS-guided gastroenterostomie bij onderliggende ###. Adviezen: - Nuchter tot deze avond: start dranken zo ok. - Zo pijnvrij morgen: herstart voeding met MDS1/soep/yoghurt. - Traagprogressief voeding uit te breiden naar uiteindelijk quasi volledig dieet over een duur van 7 dagen.', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('hyperpll', 'Hyperplastische linkszijdige poliepjes werden in situ gelaten.', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('propp', 'propofolsedatie.', '8798.0');
INSERT INTO dbo.Mnemonics (mnemonic, descriptionNL, author_id) VALUES ('afww', 'gezien mijn tijdelijke afwezigheid aldan (i.k.v. bijkomende endoscopische opleiding) werd deze controle gepland bij collega Bossuyt.', '8798.0');
